import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana', 'Ben Arous', 'Mahdia'];

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    tarifs_matieres: [], photo_url: null
  });
  const [structure, setStructure] = useState([]); 
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  // Modales
  const [showCertModal, setShowCertModal] = useState(false);
  const [newCert, setNewCert] = useState({ titre: '', description: '' });
  const [selectedFile, setSelectedFile] = useState(null);

  useEffect(() => {
    fetchProfileData();
  }, [user]);

  const fetchProfileData = async () => {
    try {
      // 1. Charger mes infos
      const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
      const res = await api.get(route);
      setForm(res.data);

      // 2. Charger le catalogue (Cascade)
      if (user?.role === 'professeur') {
        const resStruct = await api.get('/api/admin/referentiel/structure');
        setStructure(resStruct.data);
      }
      setLoading(false);
    } catch (e) {
      console.error("Erreur CORS ou API :", e);
      setLoading(false);
    }
  };

  // --- GESTION DES CHAMPS ---
  const isSelected = (matId, nivId) => 
    form.tarifs_matieres?.some(t => t.matiere_id === matId && t.niveau_id === nivId);

  const getTarif = (matId, nivId) => 
    form.tarifs_matieres?.find(t => t.matiere_id === matId && t.niveau_id === nivId)?.tarif || '';

  const handleToggleMatiere = (matId, nivId) => {
    let updated = [...(form.tarifs_matieres || [])];
    if (isSelected(matId, nivId)) {
      updated = updated.filter(t => !(t.matiere_id === matId && t.niveau_id === nivId));
    } else {
      updated.push({ matiere_id: matId, niveau_id: nivId, tarif: 20 });
    }
    setForm({ ...form, tarifs_matieres: updated });
  };

  const handlePriceChange = (matId, nivId, price) => {
    const updated = form.tarifs_matieres.map(t => 
      (t.matiere_id === matId && t.niveau_id === nivId) ? { ...t, tarif: parseFloat(price) || 0 } : t
    );
    setForm({ ...form, tarifs_matieres: updated });
  };

  // --- SAUVEGARDE TOTALE ---
  async function handleSave() {
    try {
      const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
      await api.put(route, {
        nom: form.user_nom, 
        prenom: form.user_prenom, 
        ville: form.ville,
        telephone: form.telephone, 
        bio: form.bio,
        tarifs_complets: form.tarifs_matieres 
      });
      setSaved(true); 
      setTimeout(() => setSaved(false), 3000);
      alert("✅ Profil et tarifs enregistrés !");
    } catch (e) { alert('Erreur lors de la sauvegarde'); }
  }

  const handleCertUpload = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('titre', newCert.titre);
    formData.append('file', selectedFile);
    try {
      await api.post('/api/professeurs/me/certificats', formData, { headers: { 'Content-Type': 'multipart/form-data' } });
      setShowCertModal(false); fetchProfileData();
    } catch (e) { alert("Erreur upload"); }
  };

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '10px 14px', fontSize: '.88rem', outline: 'none', width: '100%', marginBottom: '10px' };

  if (loading) return <div style={{padding: 50, textAlign: 'center'}}>Chargement...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>

      <div style={{ display: 'flex', alignItems: 'center', gap: 20, marginBottom: 30 }}>
        <div style={{ width: 80, height: 80, borderRadius: '50%', background: 'var(--accent)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '2rem' }}>👨‍🏫</div>
        <div>
           <h2 style={{fontFamily:'Syne'}}>{form.user_prenom} {form.user_nom}</h2>
           <p style={{color:'var(--text2)'}}>Professeur</p>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '450px 1fr', gap: 30 }}>

        {/* COLONNE IDENTITÉ */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20 }}>👤 Mon Identité</h3>

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Prénom</label>
            <input style={inp} value={form.user_prenom} onChange={e => setForm({...form, user_prenom: e.target.value})} />

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Nom</label>
            <input style={inp} value={form.user_nom} onChange={e => setForm({...form, user_nom: e.target.value})} />

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Email</label>
            <input style={{...inp, opacity: 0.7}} value={form.email} disabled />

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Téléphone</label>
            <input style={inp} value={form.telephone || ''} onChange={e => setForm({...form, telephone: e.target.value})} placeholder="+216..." />

            <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Ville</label>
            <select style={inp} value={form.ville} onChange={e => setForm({...form, ville: e.target.value})}>
               {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
            </select>

            <button onClick={handleSave} style={{ width: '100%', background: 'var(--accent)', color: '#fff', border: 'none', padding: 14, borderRadius: 12, fontWeight: 600, marginTop: 10 }}>
               {saved ? '✅ Enregistré !' : 'Sauvegarder les modifications'}
            </button>
          </div>

          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
             <h3 style={{marginBottom:15}}>📜 Diplômes</h3>
             <button onClick={() => setShowCertModal(true)} style={{ width:'100%', border:'2px dashed var(--border)', background:'none', color:'var(--text2)', padding:15, borderRadius:12 }}>+ Ajouter un diplôme</button>
          </div>
        </div>

        {/* COLONNE MATIÈRES */}
        <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
          <h3 style={{ marginBottom: 20 }}>📚 Mes Enseignements & Tarifs</h3>

          {structure.map(dom => (
            <div key={dom.id} style={{ marginBottom: 30 }}>
              <div style={{ color: 'var(--accent)', fontWeight: 800, fontSize: '1rem', marginBottom: 15, borderBottom: '1px solid var(--border)' }}>📂 {dom.nom.toUpperCase()}</div>
              {dom.niveaux?.map(niv => (
                <div key={niv.id} style={{ marginLeft: 15, marginBottom: 20 }}>
                  <div style={{ fontWeight: 700, fontSize: '.9rem', marginBottom: 10 }}>🎓 {niv.nom}</div>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                    {niv.matieres?.map(mat => {
                      const active = isSelected(mat.id, niv.id);
                      return (
                        <div key={mat.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: active ? 'rgba(108,99,255,0.08)' : 'var(--surface2)', padding: '10px 15px', borderRadius: 12, border: active ? '1px solid var(--accent)' : '1px solid transparent' }}>
                          <label style={{ fontSize: '.85rem', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 10 }}>
                            <input type="checkbox" checked={active} onChange={() => handleToggleMatiere(mat.id, niv.id)} />
                            {mat.nom}
                          </label>
                          {active && (
                            <input type="number" value={getTarif(mat.id, niv.id)} onChange={(e) => handlePriceChange(mat.id, niv.id, e.target.value)} style={{ width: 55, background: 'var(--bg)', color: '#fff', border: 'none', textAlign: 'center', borderRadius: 8 }} />
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}
            </div>
          ))}
          <button onClick={handleSave} style={{ width: '100%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', color: '#fff', border: 'none', padding: 18, borderRadius: 15, fontWeight: 700 }}>
            Enregistrer mon catalogue de cours
          </button>
        </div>
      </div>

      {/* MODALE DIPLÔME */}
      {showCertModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.8)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ background: 'var(--surface)', padding: 30, borderRadius: 25, width: 400, border: '1px solid var(--border)' }}>
                <h3 style={{marginBottom:20}}>Nouveau Diplôme</h3>
                <form onSubmit={handleCertUpload}>
                    <input style={inp} placeholder="Titre" onChange={e => setNewCert({...newCert, titre: e.target.value})} required />
                    <input type="file" style={{margin:'10px 0'}} onChange={e => setSelectedFile(e.target.files[0])} required />
                    <button type="submit" style={{ width:'100%', background:'var(--accent)', color:'#fff', padding:12, borderRadius:12, border:'none', fontWeight:700 }}>Enregistrer</button>
                    <button type="button" onClick={() => setShowCertModal(false)} style={{ width:'100%', background:'none', color:'#fff', marginTop:10, border:'none' }}>Annuler</button>
                </form>
            </div>
        </div>
      )}
    </div>
  );
}
